dashboard.definition:
{
    "title": "Blutdepot",
    "description": "Blutdepot: Bestand an Erythrozyten-, Thrombozytenkonzentraten und Plasma je Blutgruppe, Transfusionen, abgesetzte OPs",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Zeitraum",
            "options": {
                "token": "global_time",
                "defaultValue": "-4h@m,now"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        },
        "tokens": {
            "default": {
                "blood_group": {
                    "value": "*"
                }
            }
        }
    },
    "dataSources": {
        "ds_inv": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:bloodbank:inventory\" earliest=-20m\n| stats latest(units_available) as units_available latest(min_stock) as min_stock latest(target_stock) as target_stock latest(expiring_48h) as expiring_48h latest(units_reserved) as units_reserved latest(days_of_supply) as days_of_supply latest(status) as status by product product_name blood_group",
                "enableSmartSources": true
            },
            "name": "Bestand je Produkt und Blutgruppe"
        },
        "ds_k_ek": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_inv",
                "query": "| where product=\"EK\" | stats sum(units_available) as \"EK gesamt\""
            }
        },
        "ds_k_crit": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_inv",
                "query": "| where status=\"kritisch\" | stats count as Kritisch"
            }
        },
        "ds_k_low": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_inv",
                "query": "| where status=\"niedrig\" | stats count as Niedrig"
            }
        },
        "ds_k_exp": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_inv",
                "query": "| stats sum(expiring_48h) as \"Verfall 48 h\""
            }
        },
        "ds_k_trans": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:bloodbank:transfusion\" | timechart span=1h count as Ausgaben",
                "enableSmartSources": true
            }
        },
        "ds_k_denied": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:bloodbank:transfusion\" status=\"Ausgabe abgelehnt*\" | stats count as Abgelehnt",
                "enableSmartSources": true
            }
        },
        "ds_ek_trend": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_metrics metric_name=\"sakh.blood.units_available\" product=\"EK\" blood_group=\"$blood_group$\" BY blood_group span=10m\n| timechart span=10m avg(v) by blood_group",
                "enableSmartSources": true
            },
            "name": "EK-Bestand je Blutgruppe"
        },
        "ds_fill": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as value WHERE index=demo_sakh_metrics metric_name=\"sakh.blood.fill_pct\" BY product blood_group span=30m\n| eval series=product.\" \".blood_group | timechart span=30m limit=0 avg(value) by series",
                "enableSmartSources": true
            }
        },
        "ds_days": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_inv",
                "query": "| eval Status=status | sort product days_of_supply\n| table product blood_group units_available units_reserved min_stock target_stock days_of_supply expiring_48h Status\n| rename product as Produkt blood_group as Blutgruppe units_available as Bestand units_reserved as Reserviert min_stock as Minimum target_stock as Soll days_of_supply as \"Reichweite (Tage)\" expiring_48h as \"Verfall 48 h\""
            }
        },
        "ds_trans_dept": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:bloodbank:transfusion\" blood_group=\"$blood_group$\" | chart count over department by product",
                "enableSmartSources": true
            }
        },
        "ds_trans": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:bloodbank:transfusion\" blood_group=\"$blood_group$\"\n| eval Zeit=strftime(_time, \"%d.%m. %H:%M\") | table Zeit unit_id product blood_group units department ward indication status\n| rename unit_id as Konserve product as Produkt blood_group as Blutgruppe units as Einheiten department as Abteilung ward as Station indication as Indikation status as Status | head 50",
                "enableSmartSources": true
            }
        },
        "ds_or_cancel": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:or:case\" type=plan status=\"abgesetzt*\"\n| stats latest(procedure) as Eingriff latest(department) as Abteilung latest(blood_units_planned) as EK latest(planned_start) as ps by room case_id\n| eval Geplant=strftime(ps, \"%d.%m. %H:%M\") | table Geplant room Eingriff Abteilung EK | rename room as Saal EK as \"EK geplant\"",
                "enableSmartSources": true
            }
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_studio/images/nav_home.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_studio",
                        "dashboard": "kis_home",
                        "tokens": [],
                        "newTab": false
                    }
